class Solution { public:
 vector<int> shortestDistanceAfterQueries(int n,vector<vector<int>>& queries){vector<vector<int>> g(n);for(int i=0;i+1<n;++i)g[i].push_back(i+1);vector<int> ans;
 for(auto &e:queries){g[e[0]].push_back(e[1]);vector<int>d(n,-1);queue<int>q;q.push(0);d[0]=0;while(!q.empty()){int u=q.front();q.pop();for(int v:g[u])if(d[v]<0){d[v]=d[u]+1;q.push(v);}}ans.push_back(d[n-1]);}return ans;}
};
